// Generated by Claude (AI-assisted).
//
// Serves `lean.wasm` from R2 at /lean/lean.wasm.  Everything else under /lean/
// (`lean.js`, the library files) is a static Pages asset; `_routes.json` sends
// only this one path here.  `lean.wasm` is about 100 MB, over Pages' 25 MB
// limit for a static file.
//
// The binary is stored under its build id, `<version>/lean.wasm`, the layout
// of the lean4-wasm-in-browser deployment's bucket.  The page asks for it as
// `lean.wasm?v=<version>`; an unknown or missing version is refused rather than
// answered with a different build, whose library files would not match.

export async function onRequest({ request, env }) {
  if (request.method !== 'GET' && request.method !== 'HEAD') {
    return new Response('Method not allowed', { status: 405 })
  }
  const version = new URL(request.url).searchParams.get('v') || env.LEAN_VERSION
  if (!version || !/^[0-9a-zA-Z._-]+$/.test(version)) {
    return new Response('Missing or invalid ?v=', { status: 400 })
  }
  const object = await env.LEAN_ASSETS.get(`${version}/lean.wasm`)
  if (!object) return new Response(`No lean.wasm for build ${version}`, { status: 404 })

  const headers = new Headers()
  object.writeHttpMetadata(headers)
  headers.set('etag', object.httpEtag)
  headers.set('content-type', 'application/wasm')
  // Each build lives under its own version, so the bytes behind a URL never change.
  headers.set('cache-control', 'public, max-age=31536000, immutable')
  // `_headers` does not apply to Function responses, so the isolation headers
  // the worker threads need are set here as well.
  headers.set('cross-origin-resource-policy', 'same-origin')
  headers.set('cross-origin-embedder-policy', 'require-corp')
  headers.set('cross-origin-opener-policy', 'same-origin')
  return new Response(request.method === 'HEAD' ? null : object.body, { headers })
}
